```csharp
class PriorityQueue<T> where T : IComparable<T>
{
	List<T> _heap = new List<T>();

	// O(logN)
	public void Push(T data)
	{
		// 힙의 맨 끝에 새로운 데이터를 삽입한다
		_heap.Add(data);

		int now = _heap.Count - 1;
		// 도장깨기를 시작
		while (now > 0)
		{
			// 도장깨기를 시도
			int next = (now - 1) / 2;
			if (_heap[now].CompareTo(_heap[next]) < 0)
				break; // 실패

			// 두 값을 교체한다
			T temp = _heap[now];
			_heap[now] = _heap[next];
			_heap[next] = temp;

			// 검사 위치를 이동한다
			now = next;
		}
	}

	// O(logN)
	public T Pop()
	{
		// 반환할 데이터를 따로 저장
		T ret = _heap[0];

		// 마지막 데이터를 루트로 이동한다
		int lastIndex = _heap.Count - 1;
		_heap[0] = _heap[lastIndex];
		_heap.RemoveAt(lastIndex);
		lastIndex--;

		// 역으로 내려가는 도장깨기 시작
		int now = 0;
		while (true)
		{
			int left = 2 * now + 1;
			int right = 2 * now + 2;

			int next = now;
			// 왼쪽값이 현재값보다 크면, 왼쪽으로 이동
			if (left <= lastIndex && _heap[next].CompareTo(_heap[left]) < 0)
				next = left;
			// 오른값이 현재값(왼쪽 이동 포함)보다 크면, 오른쪽으로 이동
			if (right <= lastIndex && _heap[next].CompareTo(_heap[right]) < 0)
				next = right;

			// 왼쪽/오른쪽 모두 현재값보다 작으면 종료
			if (next == now)
				break;

			// 두 값을 교체한다
			T temp = _heap[now];
			_heap[now] = _heap[next];
			_heap[next] = temp;
			// 검사 위치를 이동한다
			now = next;
		}

		return ret;
	}

	public int Count()
	{
		return _heap.Count;
	}
}
```

## keyword : abstract

- 클래스 앞에 abstract를 쓰면 추상 클래스가 된다.
- 추상클래스의 함수에 abstract를 쓰면 함수도 추상적으로 바꿀 수 있음
- 하나의 부모만 상속받을 수 있어서 유동성이 떨어진다.
- virtual과 달리 자식클래스에서 꼭 정의를 해주어야한다.
- 가상화(virtual)과 비슷한 느낌.

### abstract 사용법

- 클래스명 앞에, 추상화를 할 함수앞에 붙여쓴다.
- 추상 클래스 내 추상화하는 함수는 선언만 한다.
- 선언한 추상함수는 자식에서 재정의한다.
- abstract 사용 예시 코드
    
```csharp
abstract class Mob
{
    public abstract void Shout(); //추상 함수는 선언만 한다.
}

class Orc : Mob
{
    public override void Shout()
    {
        Console.WriteLine("록타르 오가르")
    }
}

class Slime : Mob
{
    public override void Shout()
    {
        Console.WriteLine("끈적한 소리")
    }
}
```
    

## keyword : interface

- 인터페이스는 클래스와 달리 여러개 상속받을 수 있다. (유동적)

### interface 사용법

- ' interface 이름 '
- 인터페이스에서 함수를 선언만 한다.
- 인터페이스를 상속받는 자식에서 함수를 정의한다.
- interface 사용 예시 코드
    
```csharp
abstract class Mob
{
    public abstract void Shout(); //추상 함수는 선언만 한다.
}

class Orc : Mob
{
    public override void Shout()
    {
        Console.WriteLine("록타르 오가르")
    }
}

interface IFlyable
{
    void Fly();
}

class FlyableOrc : Orc, IFlyable
{
    void Fly()
    {
        Console.WriteLine("날아요우!");
    }
}
```

