            }
        }
        ```
        
        위의 오류가 생기는 코드를 예외처리를 사용해서 수정하면...
        
        ```csharp
        @Test
        void arithmeticException() {
            //before
            String[] strings = new String[]{"hello", "crong", "coco"};
        
            try {
                for (int i = 0; i < 4; i++) {
                    System.out.println(strings[i]);
                }
            } catch (ArrayIndexOutOfBoundsException e) {
                System.out.println("Empty");
            }
        }
        ```

